const input = $json.body ?? $json;

const text = (value) => {
  if (value === null || value === undefined) return '';
  return String(value).trim();
};

const toBoolean = (value) => {
  if (typeof value === 'boolean') return value;
  return ['true', '1', 'yes', 'on'].includes(text(value).toLowerCase());
};

const clinic_name = text(input.clinic_name);
const lookback_hours = Number(input.lookback_hours ?? 72);
const future_window_hours = Number(input.future_window_hours ?? 48);
const limit = Number(input.limit ?? 100);
const confirm_escalation = toBoolean(input.confirm_escalation);

const errors = [];

if (!clinic_name) {
  errors.push({
    field: 'clinic_name',
    message: 'نام کلینیک الزامی است.',
  });
}

if (
  !Number.isInteger(lookback_hours) ||
  lookback_hours < 1 ||
  lookback_hours > 720
) {
  errors.push({
    field: 'lookback_hours',
    message: 'lookback_hours باید یک عدد صحیح بین 1 و 720 باشد.',
  });
}

if (
  !Number.isInteger(future_window_hours) ||
  future_window_hours < 1 ||
  future_window_hours > 720
) {
  errors.push({
    field: 'future_window_hours',
    message: 'future_window_hours باید یک عدد صحیح بین 1 و 720 باشد.',
  });
}

if (!Number.isInteger(limit) || limit < 1 || limit > 500) {
  errors.push({
    field: 'limit',
    message: 'limit باید یک عدد صحیح بین 1 و 500 باشد.',
  });
}

if (confirm_escalation !== true) {
  errors.push({
    field: 'confirm_escalation',
    message: 'ایجاد ارجاع انسانی باید به‌صورت صریح تأیید شود.',
  });
}

return [
  {
    json: {
      clinic_name,
      lookback_hours,
      future_window_hours,
      limit,
      confirm_escalation,
      validation_status: errors.length === 0 ? 'valid' : 'invalid',
      errors,
    },
  },
];

return [
  {
    json: {
      success: false,
      result: 'invalid_request',
      message: 'اطلاعات بررسی عدم پاسخ ناقص یا نامعتبر است.',
      handoff_task_count: 0,
      handoff_tasks: [],
      errors: $json.errors ?? [],
    },
  },
];
